-- 202611020026: SKU resmi dari Item Library DC TIGALAPAN, 2026-11-02.
-- 6.052 SKU resmi; 1.243 item tanpa SKU tidak diberi kode rekaan.
-- Rujukan: ekspor Item Library CSV yang disediakan user.
-- WAJIB backup Supabase database dulu dan jalankan setelah migrasi 025.
-- Repo ini TIDAK terhubung langsung ke database produksi. Eksekusi di SQL Editor project SO.
-- Transaksional: jika ditemukan benturan, SEMUA perubahan di-rollback.
-- SO historis yang archived, BA signed / exported / cleaned TIDAK diubah.
-- Semua nominal, qty, alasan, dan catatan counting dipertahankan.

begin;
create table if not exists public.tsi_so_item_sku_map (
 item_key text primary key,
 item_name text not null,
 official_sku text not null unique,
 category text not null default '',
 item_variant_id text not null
);
alter table public.tsi_so_item_sku_map enable row level security;
revoke all on public.tsi_so_item_sku_map from anon, authenticated;
-- Mempertahankan basis mapping untuk upload masa depan.
-- Saat migrasi berjalan, hentikan sementara upload dan counting, untuk menghindari race condition.
lock table public.tsi_so_inventory, public.tsi_so_lines, public.tsi_so_cycles,
 public.tsi_so_ba, public.tsi_so_sku_rounds in share row exclusive mode;

