-- Baris lama menggunakan nama item sebagai sku; baris yang sudah benar tidak disentuh.
-- Inventory dipetakan untuk setiap toko, sementara SO historis ditahan jika sudah diarsipkan/ditandatangani/diekspor.
create temp table _sku_inv on commit drop as
select i.store_code,i.sku old_sku,m.official_sku new_sku
from public.tsi_so_inventory i
join public.tsi_so_item_sku_map m on upper(btrim(i.item_name))=m.item_key
where upper(btrim(i.sku))=m.item_key and i.sku<>m.official_sku;

create temp table _sku_lines on commit drop as
select l.id,l.cycle_id,l.sku old_sku,m.official_sku new_sku
from public.tsi_so_lines l
join public.tsi_so_cycles c on c.id=l.cycle_id
join public.tsi_so_item_sku_map m on upper(btrim(l.item_name))=m.item_key
where upper(btrim(l.sku))=m.item_key and l.sku<>m.official_sku
 and c.archived_at is null
 and not exists (select 1 from public.tsi_so_ba b where b.cycle_id=c.id
  and (b.spv_at is not null or b.mgr_at is not null or b.exported_at is not null or b.cleaned_at is not null));

create temp table _sku_rounds on commit drop as
select r.store_code,r.sku old_sku,m.official_sku new_sku
from public.tsi_so_sku_rounds r
join public.tsi_so_item_sku_map m on upper(btrim(r.sku))=m.item_key
where r.sku<>m.official_sku;

-- Benturan PK/UNIQUE dicek terhadap HASIL AKHIR sebelum ada satu pun perubahan.
do $guard$
declare v int; bad text;
begin
 select count(*),min(x.store_code||' / '||x.sku) into v,bad from (
  select i.store_code,coalesce(m.new_sku,i.sku) sku
  from public.tsi_so_inventory i left join _sku_inv m on m.store_code=i.store_code and m.old_sku=i.sku
 ) x group by x.store_code,x.sku having count(*)>1 limit 1;
 if coalesce(v,0)>1 then raise exception 'SKU collision inventory: %. Transaksi dibatalkan.',bad; end if;
 select count(*),min(x.cycle_id::text||' / '||x.sku) into v,bad from (
  select l.cycle_id,coalesce(m.new_sku,l.sku) sku
  from public.tsi_so_lines l left join _sku_lines m on m.id=l.id
 ) x group by x.cycle_id,x.sku having count(*)>1 limit 1;
 if coalesce(v,0)>1 then raise exception 'SKU collision lines: %. Transaksi dibatalkan.',bad; end if;
 select count(*),min(x.store_code||' / '||x.sku) into v,bad from (
  select r.store_code,coalesce(m.new_sku,r.sku) sku
  from public.tsi_so_sku_rounds r left join _sku_rounds m on m.store_code=r.store_code and m.old_sku=r.sku
 ) x group by x.store_code,x.sku having count(*)>1 limit 1;
 if coalesce(v,0)>1 then raise exception 'SKU collision rounds: %. Transaksi dibatalkan.',bad; end if;
end $guard$;

-- Pindahkan reason override pada BA yang belum disahkan; hanya KEY SKU berubah, isinya tetap.
update public.tsi_so_ba b set reason_overrides = (
 select coalesce(jsonb_object_agg(coalesce(lm.new_sku,kv.key),kv.value),'{}'::jsonb)
 from jsonb_each(coalesce(b.reason_overrides,'{}'::jsonb)) kv
 left join _sku_lines lm on lm.cycle_id=b.cycle_id and lm.old_sku=kv.key
)
where b.reason_overrides is not null and b.reason_overrides <> '{}'::jsonb
 and exists (select 1 from _sku_lines lm where lm.cycle_id=b.cycle_id);

-- Audit perubahan SKU per toko, sehingga dampaknya dapat ditelusuri.
insert into public.tsi_so_audit(user_id,store_code,event,meta)
select null,z.store_code,'SKU_LIBRARY_MIGRATION',
 jsonb_build_object('inventory_converted',(select count(*) from _sku_inv x where x.store_code=z.store_code),
  'lines_converted',(select count(*) from _sku_lines x join public.tsi_so_cycles c on c.id=x.cycle_id where c.store_code=z.store_code),
  'rounds_converted',(select count(*) from _sku_rounds x where x.store_code=z.store_code))
from (select store_code from _sku_inv union select c.store_code from _sku_lines l join public.tsi_so_cycles c on c.id=l.cycle_id
 union select store_code from _sku_rounds) z;

-- Dua tahap sementara untuk menghindari benturan ketika beberapa kode saling bertukar.
update public.tsi_so_inventory i
set sku='__TSI_026_'||md5(i.store_code||'/'||i.sku)
from _sku_inv m where i.store_code=m.store_code and i.sku=m.old_sku;
update public.tsi_so_inventory i set sku=m.new_sku
from _sku_inv m where i.store_code=m.store_code
 and i.sku='__TSI_026_'||md5(m.store_code||'/'||m.old_sku);

update public.tsi_so_lines l set sku='__TSI_026_'||md5(l.id::text)
from _sku_lines m where l.id=m.id;
update public.tsi_so_lines l set sku=m.new_sku
from _sku_lines m where l.id=m.id;

update public.tsi_so_sku_rounds r set sku='__TSI_026_'||md5(r.store_code||'/'||r.sku)
from _sku_rounds m where r.store_code=m.store_code and r.sku=m.old_sku;
update public.tsi_so_sku_rounds r set sku=m.new_sku
from _sku_rounds m where r.store_code=m.store_code
 and r.sku='__TSI_026_'||md5(m.store_code||'/'||m.old_sku);

-- Perbaiki daftar scope SKU dan aturan tim untuk jadwal/COUNTING aktif.
create or replace function public.tsi_so_026_rewrite_array(p_list jsonb)
returns jsonb language sql stable security definer set search_path = '' as $fn$
 select case when p_list is null or jsonb_typeof(p_list)<>'array' then p_list
 else (select coalesce(jsonb_agg(to_jsonb(coalesce(m.official_sku, e.s)) order by e.ord),'[]'::jsonb)
 from jsonb_array_elements_text(p_list) with ordinality as e(s,ord)
 left join public.tsi_so_item_sku_map m on m.item_key=upper(btrim(e.s))) end
$fn$;
revoke all on function public.tsi_so_026_rewrite_array(jsonb) from public, anon, authenticated;

update public.tsi_so_cycles c
set scope_skus=public.tsi_so_026_rewrite_array(c.scope_skus),
 scope_rule=case when jsonb_typeof(c.scope_rule)='object'
  then jsonb_set(c.scope_rule,'{skus}',public.tsi_so_026_rewrite_array(coalesce(c.scope_rule->'skus','[]'::jsonb)),true)
  else c.scope_rule end,
 team_map=case when jsonb_typeof(c.team_map)='array' then
  (select coalesce(jsonb_agg(
   case when jsonb_typeof(t.v->'rule')='object' then
    jsonb_set(t.v,'{rule,skus}',public.tsi_so_026_rewrite_array(coalesce(t.v->'rule'->'skus','[]'::jsonb)),true)
    else t.v end order by t.ord),'[]'::jsonb)
   from jsonb_array_elements(c.team_map) with ordinality t(v,ord))
  else c.team_map end
where c.archived_at is null
 and not exists(select 1 from public.tsi_so_ba b where b.cycle_id=c.id
  and (b.spv_at is not null or b.mgr_at is not null or b.exported_at is not null or b.cleaned_at is not null))
 and (c.scope_skus is not null or c.scope_rule is not null or c.team_map is not null);

drop function public.tsi_so_026_rewrite_array(jsonb);

-- Supaya sinkronisasi ulang rasio tidak mengembalikan SKU nama untuk histori terlindungi.
create or replace function public.tsi_so_rounds_resync(p_store text, p_apply boolean default false)
returns jsonb language plpgsql security definer set search_path = '' as $fn$
declare who text; arch int; changed int; sample jsonb;
begin
 select role into who from public.tsi_so_users where user_id=auth.uid() and active;
 if who is distinct from 'admin' then raise exception 'Hanya Admin.'; end if;
 if not exists(select 1 from public.tsi_so_stores where code=p_store) then raise exception 'Kode toko tidak ditemukan.'; end if;
 create temp table if not exists _rr_new(sku text primary key, n int) on commit drop;
 create temp table if not exists _rr_old(sku text primary key, n int) on commit drop;
 delete from _rr_new; delete from _rr_old;
 insert into _rr_new
 select coalesce(m.official_sku,l.sku),count(distinct c.id)::int
 from public.tsi_so_cycles c join public.tsi_so_lines l on l.cycle_id=c.id
 left join public.tsi_so_item_sku_map m
  on upper(btrim(l.sku))=m.item_key and upper(btrim(l.item_name))=m.item_key
 where c.store_code=p_store and c.rounds_recorded and c.archived_at is null
 group by coalesce(m.official_sku,l.sku);
 insert into _rr_old select r.sku,r.so_count from public.tsi_so_sku_rounds r where r.store_code=p_store;
 select count(*) into arch from public.tsi_so_cycles where store_code=p_store and rounds_recorded and archived_at is not null;
 select count(*) into changed from (
  select coalesce(o.sku,nw.sku) sku, coalesce(o.n,0) old_n, coalesce(nw.n,0) new_n
  from _rr_old o full join _rr_new nw on nw.sku=o.sku) d where d.old_n<>d.new_n;
 select coalesce(jsonb_agg(x order by x->>'sku'),'[]'::jsonb) into sample from (
  select jsonb_build_object('sku',coalesce(o.sku,nw.sku),'dari',coalesce(o.n,0),'menjadi',coalesce(nw.n,0)) x
  from _rr_old o full join _rr_new nw on nw.sku=o.sku
  where coalesce(o.n,0)<>coalesce(nw.n,0) limit 50) t;
 if p_apply then
  delete from public.tsi_so_sku_rounds where store_code=p_store;
  insert into public.tsi_so_sku_rounds(store_code,sku,so_count,last_date)
   select p_store,n.sku,n.n,current_date from _rr_new n;
  insert into public.tsi_so_audit(user_id,store_code,event,meta)
   values(auth.uid(),p_store,'ROUNDS_RESYNC',jsonb_build_object('changed',changed,'archived_not_counted',arch));
 end if;
 return jsonb_build_object('applied',p_apply,'changed',changed,'archived_recorded',arch,'sample',sample);
end; $fn$;
revoke all on function public.tsi_so_rounds_resync(text,boolean) from public, anon;
grant execute on function public.tsi_so_rounds_resync(text,boolean) to authenticated;

-- Upload CSV: jika file tidak punya kolom SKU, coba ambil dari Item Library.
-- SKU tidak ditemukan DAN input masih nama item -> tolak secara eksplisit.
-- Jika file sudah memuat SKU asli (non nama item), dipertahankan bila tak ada mapping.
create or replace function public.tsi_so_upload(p_store text,p_rows jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $fn$
declare r text; v_count integer; v_bad integer; v_id uuid; v_synced integer; v_locked integer;
 v_rows jsonb; v_unknown text; v_mapped integer;
begin
 r:=public.tsi_so_authorize(p_store,true);
 if r not in ('store','admin','spv') then raise exception 'Tidak memiliki akses upload.'; end if;
 if jsonb_typeof(p_rows) is distinct from 'array' then raise exception 'Data inventory harus array.'; end if;
 v_count:=jsonb_array_length(p_rows);
 if v_count not between 1 and 10000 then raise exception 'Upload 1 sampai 10000 SKU per batch.'; end if;
 select count(*) into v_mapped from jsonb_array_elements(p_rows) j
 join public.tsi_so_item_sku_map m on m.item_key=upper(btrim(j->>'name'));
 select coalesce(jsonb_agg(
   jsonb_set(j,'{sku}',to_jsonb(coalesce(m.official_sku,
    nullif(upper(btrim(j->>'sku')),''),'')) ,true) order by ord),'[]'::jsonb)
 into v_rows from jsonb_array_elements(p_rows) with ordinality z(j,ord)
 left join public.tsi_so_item_sku_map m on m.item_key=upper(btrim(j->>'name'));
 -- Cegah nama Item dijadikan kode. Menolak hanya jika tidak ada SKU resmi/eksplisit.
 select string_agg(left(coalesce(j->>'name','(kosong)'),60),'; ') into v_unknown
 from (select j from jsonb_array_elements(v_rows) j
  where nullif(btrim(j->>'sku'),'') is null or
   upper(btrim(coalesce(j->>'sku','')))=upper(btrim(coalesce(j->>'name','')))
  limit 5) x;
 if v_unknown is not null then
  raise exception 'SKU resmi tidak tersedia untuk item: %. Isi kolom SKU pada file inventory / lengkapi Item Library dahulu.',v_unknown;
 end if;
 select count(*) into v_bad from jsonb_array_elements(v_rows) j
 where length(btrim(coalesce(j->>'sku',''))) not between 1 and 80
    or length(btrim(coalesce(j->>'name',''))) not between 1 and 250
    or coalesce(j->>'ending','') !~ '^[0-9]{1,12}$'
    or coalesce(nullif(j->>'cost',''),'0') !~ '^[0-9]{1,12}(\.[0-9]{1,2})?$'
    or coalesce(nullif(j->>'retail',''),'0') !~ '^[0-9]{1,12}(\.[0-9]{1,2})?$';
 if v_bad > 0 then raise exception 'Ada % baris tidak valid (SKU, nama, ending, cost, retail).',v_bad; end if;
 select count(*) into v_bad from (
  select upper(btrim(j->>'sku')) sku from jsonb_array_elements(v_rows) j group by 1 having count(*)>1) z;
 if v_bad>0 then raise exception 'Ada SKU duplikat setelah pencocokan Item Library: %.',v_bad; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('tsi_so_store:'||p_store));
 insert into public.tsi_so_uploads(store_code,uploaded_by,sku_count) values(p_store,auth.uid(),v_count) returning id into v_id;
 delete from public.tsi_so_inventory where store_code=p_store;
 insert into public.tsi_so_inventory(store_code,sku,item_name,category,ending,cost,retail_price,upload_id)
 select p_store,upper(btrim(j->>'sku')),btrim(j->>'name'),left(coalesce(j->>'category',''),120),
 (j->>'ending')::bigint,coalesce(nullif(j->>'cost',''),'0')::numeric,
 coalesce(nullif(j->>'retail',''),'0')::numeric,v_id from jsonb_array_elements(v_rows) j;
 update public.tsi_so_lines l set system_at_start=coalesce((select i.ending from public.tsi_so_inventory i
  where i.store_code=p_store and i.sku=l.sku),0)
 where l.cycle_id in (select c.id from public.tsi_so_cycles c
  where c.store_code=p_store and c.status in ('COUNTING','RECOUNT'));
 get diagnostics v_synced = row_count;
 select count(*) into v_locked from public.tsi_so_lines l
 where l.cycle_id in (select c.id from public.tsi_so_cycles c
  where c.store_code=p_store and c.status='SUBMITTED');
 insert into public.tsi_so_audit(user_id,store_code,event,meta)
 values(auth.uid(),p_store,'UPLOAD',jsonb_build_object('upload_id',v_id,'skus',v_count,
  'sku_auto_from_library',v_mapped,'synced_lines',v_synced,'locked_lines',v_locked));
 return jsonb_build_object('upload_id',v_id,'sku_count',v_count,'sku_auto_from_library',v_mapped,
  'synced_lines',v_synced,'locked_lines',v_locked);
end; $fn$;
revoke all on function public.tsi_so_upload(text,jsonb) from public, anon;
grant execute on function public.tsi_so_upload(text,jsonb) to authenticated;

-- Ringkasan jumlah mapping yang diterapkan pada transaksi ini.
select (select count(*) from public.tsi_so_item_sku_map) as sku_library,
       (select count(*) from _sku_inv) as inventory_converted,
       (select count(*) from _sku_lines) as so_lines_converted,
       (select count(*) from _sku_rounds) as rounds_converted,
       (select count(*) from public.tsi_so_inventory i where upper(btrim(i.sku))=upper(btrim(i.item_name))) as inventory_still_name_as_sku;
commit;
